 getRunBaseMaxHp(){const foundation=UPGRADES.find(u=>u.id==='foundation'),multiplier=foundation?.effects?.find(e=>e.stat==='baseHp')?.value||1.12,stacks=(this.upgrades||[]).filter(id=>id==='foundation').length;return B.baseHp*(1+(this.meta?.fortress||0)*.05)*Math.pow(multiplier,stacks)}
