  if(mastery>=5){if(p.id==='repeater')s.cooldown*=.9;if(p.id==='bonkChoy')s.attackInterval*=.95;if(p.id==='cabbagePult')s.splashRadius*=1.1;if(p.id==='potatoMine')s.armTime*=.85;if(p.id==='wallNut')s.regen+=.05}
