 place(id,x,y){const def=PLANTS.find(p=>p.id===id),cost=this.getPlantCost(id,{x,y});if(!def||!['intermission','playing'].includes(this.state)||this.paused||this.cooldowns[id]>0||!this.valid(x,y)||this.sun<cost)return false;const firstOfRun=this.runFieldCount(id)===0,firstOfGarden=this.gardenFieldCount(id)===0;this.sun-=cost;const provisional={...def,x,y,hp:def.hp,maxHp:def.hp,firstOfRun,firstOfGarden},s=this.stats(provisional),maxHp=s.hp*(id==='wallNut'&&firstOfRun&&(this.runMastery.wallNut||0)>=10?1.1:1),plant={...def,x,y,hp:maxHp,maxHp,timer:0,productionTimer:0,age:0,attacks:0,uid:++this.nextId,paid:cost,lastHitAgo:99,lastDamageTaken:0,firstOfRun,firstOfGarden,gardenId:this.simulationGarden.id};this.plants.push(plant);this.cooldowns[id]=s.cooldown*getGardenConditionModifier(this.simulationGarden,'seedCooldownMultiplier')*this.relicModifier('seedCooldownMultiplier',1);this.placed++;this.plantUsage[id]++;this.metrics.plantsPlaced++;this.plantRevision++;this.events.emit('plant:placed',{id,x,y,cost,gardenId:this.simulationGarden.id});return true}
